INSERT IGNORE INTO permissions(component,action,description) VALUES('analytics','read','Consulter les indicateurs et détails'),('analytics','create','Créer des analyses'),('analytics','validate','Valider les alertes analytiques'),('analytics','update','Traiter les alertes analytiques'),('analytics','delete','Archiver les analyses'),('analytics','administer','Administrer le pilotage');
INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.component='analytics' WHERE r.slug IN('administrateur','administrateur-systeme');
INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.component='analytics' AND p.action='read' WHERE r.slug IN('direction','directeur-general','directeur-financier','auditeur','comptable','directeur-site','responsable-site','gestionnaire-stock','operateur-production','chauffeur-logistique');
